  // 入った。** **着手時点でこの説明文は `view.actions` について1文字も書いていなかった**
  // (2026-08-04 実測: `操作起点` も `actions` も、ワークフローの `actions` を除いて0件)——
  // **その沈黙は本タスクが作ったものではないが、今日はより重い** —— **書ける形が2つに
  // 分岐したからである。** したがって3キーぶんまとめて埋める。
  // **【禁止】「ボタンで処理を走らせられるようになった」と書かない**(ADR-0100 §限界3)——
  // **ワークフローを名指しで起こす形は1つも無い。**
  // **【禁止】「二重押しが防げる」と書かない**(同 §限界1)—— **冪等ではない。**
  // **【V5-M21-T05 / `L-G1` / ADR-0171 無効化条文7 で外した】** **着手前ここには
