  // 在った。** **今日は偽である** —— **ADR-0171(門A / 判定 = 限定採用)が一覧の行の
  // 操作起点を通し、`visible_when` は一覧では行ごとに1回ずつ評価される。**
  // **代わりに置く禁止**:
  // **【禁止】「一覧から何でも呼べるようになった」と書かない**(ADR-0171 §限界5)——
  // **複数行をまとめて対象にする形は今日も1つも無い。**
  // **【禁止】「一覧の set 形が書ける」と書かない**(ADR-0171 限定10 の順序拘束)。
  // **【禁止】「条件で隠したから安全である」と書かない**(ADR-0101 限定6)。
  // **【禁止】「2段階の確認ができる」と書かない**(ADR-0102 §限界1)。
  // **【V5-M22-T05 / `L-G5` / `L-G6` / `L-G7` / ADR-0173 無効化条文4 で書き換えた】**
  // **着手前ここには逐語「**3つ目の形はありません**(2つを1つの要素に混ぜても差分全体が
  // 拒否されます)。」が在った。** **今日は偽である** —— **ADR-0173(門A / 判定 = 限定採用)
  // が `$defs/view_action.oneOf` に3形目(行き先の宣言)を足した。**
  // **ADR-0173 §Decision 6 の4 が「全部」を無効化と名指しした唯一の条文がこれである。**
  // **代わりに置く禁止**:
