  // 不正確になった。ただし本題(消したフィールドの値だけを、その後に入れたデータを保ったまま
  // 戻す手段は無い)は redo を入れても1ミリも変わらない。「redo があるので安全」には緩めない。
  "消えた値の退避先はスナップショットだけで、それを戻す手段(undo と、その undo をやり直す redo)は" +
  "いずれもデータベース全体を巻き戻します。" +
  "undo はデータベース全体を巻き戻します" +
  "(redo も直前の undo が戻した時点へ、やはりデータベース全体を巻き戻すだけで、" +
  "消したフィールドの値だけを選んで戻せるわけではありません)。" +
  "したがって、消したあとに入力されたレコードを保ったまま、" +
  "消したフィールドの値だけを戻す手段はありません。" +
  "「スナップショットがあるので戻せます」「あとで復元できます」とユーザに説明してはいけません。";

// --- V0-P7-T04: 実地観察に基づく追記 ------------------------------------------------
//
// 以下は v0 の実地確認(CP-5 / CP-6 / ブートストラップ課題)で **AI が実際に外した箇所**
// への手当てである。出典は `docs/v0-findings.md` §3、判断の記録は `docs/v0-t04-record.md`。
//
// 定数に切り出す理由は上の3定数と同じ(R12)。「それらしい部分文字列」ではなく
// **この定数そのもの**を `descriptions.test.ts` が照合するので、言い回しを変えると
// テストが落ちる。説明文は v1 で必ず書き換えられ、そのとき冗長な行から削られる。
// ここは実地で外した実績のある箇所なので、黙って消えないようにしてある。
//
// **どれもプロンプトである。** 守らせる強制力はカーネルにも MCP にも無い(F-41)。
// 発生を減らすことしか期待していない。

/**
 * F-22: `intent` は逐語で書く。
 *
 * 002/T4 で AI が自己申告した —— 3件すべてで人間の依頼文を微妙に言い換えて記録して
 * いた(語尾を削る / 接続詞を落とす / 語を足す)。意味は変わっていないが逐語ではない。
 * **AI の判断ミスではなく指示の不在である。** 説明文に「逐語で」が書かれておらず、
 * AI は「読みやすく整える」を良かれと思って行っていた。
 *
 * 効き方の重さ: 憲法5 で changelog は要件定義書であり、CP-6 で `_changelog` は
 * **画面**になった。ここに入る文字列はそのまま製品の UI に出る。しかも v0 には
 * 訂正手段が無い(F-12)ので、劣化した意図は永久に残る。
 */
export const INTENT_VERBATIM =
  "**ユーザの依頼文を逐語で書くこと。** 要約・整形・語尾の調整・接続詞の削除をしない。" +
  "読みやすく整えたくなるが、整えてはいけない。" +
  "この文字列は変更履歴の画面にそのまま表示され、後から訂正する手段が無い。" +
  "複数の依頼をまとめて1つの差分にするなら、それぞれの依頼文をそのまま並べること。";

/**
 * F-23: 4つの op の最小 JSON 例。
 *
 * F-4 の対処。`update_view` は「既存の何かを指す `view`(文字列)+ 変更内容 `changes`」
 * という**二層構造を持つ唯一の op** であり、他3 op から形を類推すると必ず外れる。
 * この非対称が説明文で補われていなかった。実地では CP-6 の4試行 + CP-5 で
 * 計5セッションにわたり独立に再発している。
 *
 * **効果の見積もり**: 全件がエラー1回で自己修正できていた(F-14)ので、
 * これは「往復が1回減る」効果であって「詰まりを解消する」効果ではない。
 *
 * **V1-M0-T03 で (4) を書き換えた。** T04 の時点では「sort はオブジェクト1つで
 * あって配列ではない」と書いていた —— `docs/v0-t04-record.md` §F-23 のとおり、
 * 最初に書いた例が配列で、**それが当時のスキーマに対して誤りだったので直された**もの
 * である。T03 でスキーマ側を配列に揃えた(F-2)ので、**例と注意書きを同時に直さないと
 * 説明文が嘘になる**(計画書 V1-M0-T03 の完了条件4)。
 * この定数の例は `src/mcp/tools/write.test.ts` が**実際に apply_diff へ流して**
 * 通ることを確かめている。目視レビューでは4件とも見つからなかった、というのが
 * T04 の教訓である。
 */
/**
 * V1-M2-T02: **実行履歴テーブルの列の規約(ひな形)。**
 *
 * ## なぜここにあるのか
 *
 * ADR-0013 §8c 問4 の決定である ——
 * **「組み込み」の実体は、カーネルの生成コードではなく MCP のツール説明文
 * (推奨スキーマのひな形)に置く。**カーネルは履歴テーブルを1つも自動生成しない
 * (限定8。`src/kernel/create-app.ts` を1バイトも変更していない)。
 * したがって**この文字列が規約の唯一の在処である。**
 *
 * ## §8d が申告済みの限界。隠さずに文面へ書いてある
 *
 * > **履歴テーブルの列名の規約は、MCP のツール説明文にしか書かれない。**
 * > AI がひな形と違う列を作れば、ワークフローの書き込みは実行時に失敗する。
 * > **参照整合性が保証するのは「テーブルが存在すること」であって
 * > 「テーブルが正しい形をしていること」ではない。**
 *
 * これは F-41 が名指しした構造そのものである —— **プロンプトであって強制力は無い。**
 * 緩和として「履歴テーブルの形をスキーマで固定する」は §8d が明示的に却下している
 * (採ると限定8 を破って「プラットフォームが守る」側に倒れる)。
 *
 * ## ⚠ これは手書きの複製である。追随が要る
 *
 * **列IDと型は `src/kernel/workflow-runner.ts` の `WORKFLOW_HISTORY_COLUMNS`
 * (および `writeHistory` が組み立てる `RecordInput`)を実測で写したものである。**
 * **値として import していない** —— `descriptions.test.ts:232-236` が
 * 「`DIFF_OPS` を import しないのは ADR-0009 限定2 の import スナップショット
 * (`scripts/kernel-import-snapshot.txt`)を増やさないためだ」という方針を記録しており、
 * 同じ理由でここも手書きにしてある。
 *
 * **したがって `WORKFLOW_HISTORY_COLUMNS` を変えたら、この定数の追随が要る。**
 *
 * **【V1-M2-T03 で追記】同じ罠がもう1つ増えた。**末尾に足した「連鎖は 20 段まで」の
 * **20 は、`workflow-runner.ts` の `WORKFLOW_MAX_DEPTH` を手で写した数字である。**
 * ここでも値として import していない —— 理由は上と同じ(import スナップショットを
 * 増やさない)。**`WORKFLOW_MAX_DEPTH` を動かしたら、この文面の数字も直すこと。**
 *
 * **歯止めは間接である。正直に書いておく。**`descriptions.test.ts` が見るのは
 * 「description に "20 段まで" という文字列が届いているか」であって、
 * **定数と突き合わせてはいない**(突き合わせるには値 import が要り、
 * `scripts/kernel-import-snapshot.txt` が1行増える)。実際に効く仕掛けは
 * `workflow-runner.test.ts` の `expect(WORKFLOW_MAX_DEPTH).toBe(20)` で、
 * **定数を動かした者は必ずそこで赤を踏む。**その赤を見たら、ここまで直しに来ること。
 * **自動では追随しない。**
 *
 * **末尾の追記のもう一方(「履歴テーブルはワークフローを発火させません」)は、
 * T03 判断2 が生んだ沈黙の破壊の宣言先である。**参照整合性を通り、適用も成功し、
 * しかし永久に発火しないワークフローが書けてしまう —— **この文面が、その事実が
 * AI に届く唯一の経路である。**消すと限界が沈黙する(憲法6)。
 * **V1-M2-T07 の実地調査で、この種の「語彙を散文で複製している非テストファイル」が
 * 3度数え落とされている**(`src/kernel/ajv-error-adapter.ts`)。**同じ罠を新しく
 * 1つ作ることになるので、追随が要ることをここに明記しておく。**
 * 歯止めは `vocabulary.test.ts` / `descriptions.test.ts`(5列と型を固定)と
 * `tools/write.test.ts`(**このひな形を実際に apply_diff へ流し、そのテーブルに
 * ワークフローが履歴を書けることまで確かめる**)である。**後者が本命で、
 * 列IDか型が実装とずれた瞬間に赤くなる。**
 *
 * ## 配送経路(新しい配線を1本も足していない)
 *
 * **`APPLY_DIFF_OP_EXAMPLES` の末尾に連結してある。**`server.ts` の `join` にも
 * `registerTool` にも手を入れていない —— `DESTRUCTIVE_CHANGE_FLOW` が
 * V1-M2-T07 で採ったのと同じ判断で、**配線を1本忘れれば「書いたが誰にも渡って
 * いない」文字列**ができるからである。`APPLY_DIFF_OP_EXAMPLES` は既に
 * `tools/write.ts:306` から `apply_diff` の description に届いており、
 * `descriptions.test.ts` の既存テストがその到達をそのまま見張る。
 * **履歴テーブルを作るのは `add_workflow` と同じ差分の中でだけなので、
 * 「差分の書き方」を述べるこの定数が意味的にも正しい置き場である。**
 *
 * ## JSON 例の書き方の制約(将来の編集者へ)
 *
 * `tools/write.test.ts` の `exampleOperations()` は
 * `APPLY_DIFF_OP_EXAMPLES` を行単位で走査して差分 op を取り出す。
 * **その抽出が `"op"` を含む行だけを拾うようにしてあるので**、ここの
 * `fields` の各行(`{ "id": ... }`)は拾われない。ひな形を1行の JSON に
 * 畳むと op 例の並び順テストが壊れるので、**複数行のままにしておくこと。**
 */
export const WORKFLOW_HISTORY_TABLE_TEMPLATE =
  "【ワークフローの実行履歴テーブル —— 列の規約(ひな形)】" +
  "ワークフローは発火するたびに history_table へ**1行**書きます(実行1回につき1行。" +
  "アクション1つにつき1行ではありません)。" +
  "**カーネルはこのテーブルを作りません。**" +
  "add_workflow と**同じ差分の中で add_table して**用意すること" +
  "(存在しないテーブルを history_table に指定した差分は、全体が拒否されます)。" +
  "列IDと型は次のとおりで、**5列すべてが必要**です。そのまま写して使うこと。\n" +
  "  {\n" +
  '    "op": "add_table",\n' +
  '    "table": {\n' +
  '      "id": "workflow-runs",\n' +
  '      "name": "実行履歴",\n' +
  '      "fields": [\n' +
  '        { "id": "ran_at", "name": "実行時刻", "type": "date" },\n' +
  '        { "id": "workflow", "name": "ワークフロー", "type": "text" },\n' +
  '        { "id": "trigger_type", "name": "きっかけ", "type": "text" },\n' +
  '        { "id": "status", "name": "結果", "type": "text" },\n' +
  '        { "id": "error", "name": "エラー", "type": "long_text" }\n' +
  "      ]\n" +
  "    }\n" +
  "  }\n" +
  "テーブルの id(上の例では workflow-runs)と name は好きに決めてよく、" +
  "history_table にその id を書きます。**変えてはいけないのはフィールドの id と type の5組**です。" +
  "各列に入る値: " +
  "ran_at = 実行した時刻(ISO8601)、" +
  "workflow = 実行されたワークフローの id、" +
  "trigger_type = 発火のきっかけ(on_create / on_update / schedule / manual のいずれか。" +
  "トリガー4種すべてが実際にこの列に書かれます)、" +
  "**この列には「誰が押したか」は入りません** —— " +
  "手動で起こしたことは manual として残りますが、押した人は残りません" +
  "(押した人は管理画面の操作記録の側にだけ残ります)。" +
  // 【`V8-M42` / `F-G15` / `ADR-0333`(`Δ5` の是正)。**旧文を逐語で残す**】
  //     "status = success / failure / suppressed の3値、" +
  // **4値目 `no_target` が入った**(`ADR-0333` 限定2)。
  "status = success / failure / suppressed / no_target の4値、" +
  "**no_target は「対象表を指定した毎日の処理が、対象を1件も得られずに発火した」ことを表します** —— " +
  "**失敗ではありません。**この行は「その日もう発火した」として数えられないので、" +
  "**同じ日に対象が1件でも増えれば、その日のうちにもう一度発火します。**" +
  // **V4-M41a(`D-V4-129` の (e)。Δ5 の是正)**: **旧文は逐語
  // 「error = 失敗したアクションの説明(成功したときは空になります)。」だった。**
  // **括弧の中は今日すでに嘘である** —— **`V4-M38` の門A 本審査が実地の実行履歴を数え、
  // `status='success'` かつ `error` が非空の行が **29件** あることを実測した**
  // (`docs/plan/v4/records/v4-m38-gate-a.md` §1-1。**29件すべてが `when` によるスキップ通知**)。
  //
  // **【区別を丸めない】`ADR-0131` 限定8 は破れていない。** 限定8 の第4列の逐語は
  // 「**0件の実行の直後**に履歴が1行増え `status` が `success` / `error` が `null` である検査1本」
  // であり、**射程は「何も書かなかった実行」に限られている。** **実測はむしろその裏づけである**
  // (29件は 0件の実行ではなく、`when` でスキップしたアクションを持つ実行である)。
  // **破れているのは「成功なら必ずエラー欄が空」という一般化の方である。**
  //
  // **双方向に書く** —— **「成功でも埋まりうる」だけを書くと「error はいつも埋まる」という
  // 逆向きの嘘になる**ので、**失敗の理由が入る**ことと、**0件の実行では空である**ことも同時に残す。
  // **`E-G60b` は 2026-08-04 に保留で閉じている**ので、**欄を分ける実装は今日も無い。**
  "error = そのアクションについての説明。" +
  "**失敗の理由だけではありません** —— " +
  "実行条件(when)に合わずスキップしたことの通知も、同じ欄に入ります" +
  "(欄を分ける手段は今日1つもありません)。" +
  "**そのため status が success の行でも error が空でないことがあります。**" +
  "**「error に文字がある = 異常」という前提で画面や通知を作らないでください** —— " +
  // 【`V8-M42` / `F-G15` / `ADR-0333`(`Δ5` の是正)。**旧の2文を逐語で残す**】
  //     "異常かどうかは status の側(success / failure / suppressed)で見ます。" +
  //     "**何も処理するものが無かった実行(0件)は status = success で error は空です。**" +
  // **2文目は今日は偽である** —— **対象表を指定した schedule の0件の実行は
  // `status = no_target` になった**(`ADR-0333` 限定2)。 **対象表を指定しない schedule と、
  // when で全アクションがスキップされた実行は今日どおり `success` である。**
  "異常かどうかは status の側(success / failure / suppressed / no_target)で見ます。" +
  "**何も処理するものが無かった実行(0件)は error は空です。**" +
  "**そのうち「対象表を指定した毎日の処理が、対象を1件も得られなかった」実行だけは " +
  "status = no_target になり、それ以外(対象表を指定しない毎日の処理など)は今日どおり status = success です。**" +
  "**status と trigger_type に select 型を使ってはいけません。**" +
  "select は options に無い値を書こうとすると、1文字違うだけで書き込みが弾かれます。" +
  "**そして弾かれた失敗を書く先が、また同じ列です** —— " +
  "status に failure を書こうとして options 不一致で弾かれると、" +
  "**その失敗の記録自体がどこにも残りません。**この循環が最も踏みやすい罠です。" +
  "text にしておけば、値の綴りが規約とずれても行は書かれ、後から読めます。" +
  "trigger_type も同じ理由で text にすること(トリガーが4種あるので、" +
  "select にすると options を4つとも正確に書かないと履歴が消えます)。" +
  // 【`V8-M42` / `F-G15` / `ADR-0333`(`Δ5` の是正)。**旧文を逐語で残す**】
  //     "**status も3値(success / failure / suppressed)なので、同じ危険がそのまま乗ります** —— " +
  // **`ADR-0072` 限定6(罠の説明文を弱めない)を守る** —— **値が1つ増えたので圧力は上がった。**
  "**status も4値(success / failure / suppressed / no_target)なので、同じ危険がそのまま乗ります** —— " +
  "値が増えたぶん options を書き漏らす確率は上がっています。text から変えないでください。" +
  "**列が1つでも足りないと、履歴は1行も書かれません。**" +
  "「書ける列だけ書く」ではなく all-or-nothing です —— " +
  "例えば error 列だけを省くと、成功している間は何も起きず、" +
  "最初の失敗が起きた瞬間に**最も知りたい1行だけ**が消えます。" +
  "reference 型で対象レコードを指す列などを**足す**のは構いません(add_field で増やせます)。" +
  "ワークフローはその列を空のまま書きます。**減らすことだけができません。**" +
  "**この5列は差分の適用時に検査されます。**" +
  "上の5組(id と type)のどれか1つでも欠けていたり型が違っていたりすると、" +
  "**差分が拒否されます**(ワークフローを add_workflow する差分も、" +
  "後から remove_field / change_field で履歴テーブルの列を崩す差分も、同じように拒否されます)。" +
  "拒否のメッセージには、何が足りないか・どう違うか・正しい形が書かれているので、" +
  "それを読んで直せます。" +
  "**検査は「ちょうど5列」ではなく「少なくともこの5列が正しい型で在ること」です** —— " +
  "他の列を足すのは構いませんし(add_field)、列の並び順も問いません。" +
  "**この検査が無かったころは、ひな形と違う列を作ると差分は通り、" +
  "ワークフローは動いているのに履歴が1行も残らず、その取りこぼしが誰にも見えませんでした。**" +
  "実地検証で3試行すべてがこの状態に陥ったため、適用時に止めるようにしたものです。\n" +
  "【重要な制限 —— 履歴テーブルはワークフローを発火させません】" +
  "**履歴テーブルへの書き込みは、どのワークフローも発火させません。**" +
  "履歴は「実行の記録」であって業務上の出来事ではないからです。" +
  "したがって、**history_table に指定されているテーブルを trigger.table に持つ" +
  "ワークフローは、差分としては受理され、適用も成功しますが、永久に発火しません。**" +
  "「実行履歴に行が増えたら通知を作る」のような監視のワークフローは書けません。" +
  "**エラーにならず、ただ静かに動かない**ので、この形を書かないこと。" +
  "履歴を見せたいときは、ワークフローではなく履歴テーブルのビューを作ってください。\n" +
  "【重要な制限 —— ワークフローの連鎖には上限があります】" +
  "ワークフローが別のワークフローを発火させる連鎖は、**20 段まで**です。" +
  "21 段目は実行されず、**status = failure の行が履歴に残ります**(黙って止まりません)。" +
  "また、**同じレコードは1回の操作で2度発火しません。**" +
  "例えば on_update のワークフローが update_record で自分自身を更新すると、" +
  "2度目の発火は抑止され、**status = suppressed** として履歴に残ります" +
  "(**抑止は失敗ではありません** —— 発火元の書込は成立します)。" +
  "どちらも無限ループを止めるための仕組みです。" +
  "履歴に「深度上限」を含む failure や、「再発火」を含む suppressed が並んでいたら、" +
  "**ワークフローが互いを発火させ合っていないか**を疑ってください。\n" +
  "【重要な制限 —— schedule トリガーは、この履歴テーブルで「今日発火したか」を覚えています】" +
  "**schedule(毎日 hour:minute)の「その日もう発火したか」の判定は、" +
  "この履歴テーブルを読んで行われます。他のどこにも記録はありません。**" +
  "そのため次のことが起きます。" +
  "(1) **履歴の行を delete_record で消すと、その日のうちに二重に発火します。**" +
  "「履歴が増えたので古い行を消す」を、その日に発火した行に対してやらないこと。" +
  "(2) **履歴テーブルの workflow 列と ran_at 列が欠けていると、schedule は発火しません。**" +
  "判定に使う列そのものが無いためです(黙って動かないのではなく、" +
  "発火せずに理由が記録されます)。" +
  // 【`V8-M42` / `F-G15` / `ADR-0333`。**上の (1)(2) と下の (3) を1文字も消していない。1項足した**】
  "(2b) **対象表を指定した毎日の処理が、対象を1件も得られずに発火した日(status = no_target)は、" +
  "「その日もう発火した」として数えません。**同じ日に対象が1件でも増えれば、その日のうちにもう一度発火します。" +
  "**対象が1日じゅう0件のままなら、その日じゅう毎周期この判定が走り続けます**" +
  "(履歴に no_target の行が周期のぶんだけ増えます。回数の上限はありません)。" +
  "**失敗(failure)や抑止(suppressed)で終わった発火は、今日どおり「発火した」として数えます** —— " +
  "**同じ日に再試行はされません。**" +
  "(3) **サーバが止まっている間に発火時刻が過ぎた場合、同じ日のうちに起動すれば" +
  "遅れて発火します。日をまたいだ分は失われ、まとめて取り戻すことはしません。**" +
  "「毎日1回まで」であって「必ず毎日1回」ではありません。" +
  "また、**発火時刻の解釈と「今日」の区切りはサーバのタイムゾーン設定で決まります**" +
  "(既定は日本時間)。**マニフェストにタイムゾーンは書けません。**";

// --- V3-M4-T02: 言葉 → トークンの統制語彙(D-G8)------------------------------------
//
// **判定の正**: `docs/adr/0007-vocabulary-governance.md` §8 の 2026-07-26 の D-G8 の行
// (**門 = 外(Δ7)/ 判定 = 将来送り / 送り先 = V3-M4-T02**)と審査記録
// `docs/plan/v3/records/v3-m4-gate-a-intake.md` §4。
//
// ## なぜここ(MCP の説明文層)に置くのか —— 憲法1 の線
//
// **統制語彙をマニフェストの語彙にする案は、憲法1(カーネルを育てない。メタサーキュラーに
// しない)違反として却下されている**(V3-M0 の問1 の結論を V3-M4-T00 が追認した)。
// マニフェストが「マニフェストの見た目設定をどう動かすか」を語り始めるからである。
// **説明文の定数として持つ案は反しない** —— 表は AI に渡す散文であって、カーネルが読んで
// 分岐する規則ではない。**カーネルは「もっと」を1度も解釈しない**(解釈するのは会話側の AI で、
// カーネルに届くのは展開された25スロットの実値だけである)。先例は ADR-0025 が
// 「賢さを定数表に閉じ、`renderStatementText` は単純置換のまま」とした形と同型である。
//
// ## T00 が確定させた「表の形」4点(実装はこれを変えない)
//
// 1. **表は「向き」ではなく行き先の実値を持つ。** ADR-0047 限定6 が式・計算・参照を
//    1つも許さないので、「1段上げる」をマニフェストに書く形は取れない。
// 2. **表の単位はスロット1個ではなく「軸1本 = スロットの組」である**(余白は6スロットで1軸)。
// 3. **段階を持たない軸で「もっと」を受け付けるなら、それが段階ではなく実値の差し替えである
//    ことを明記する。**
// 4. **`--focus-outline-style` / `--border-style` は `$defs/theme` の25スロットに無く、
//    テーマから動かせない。表に入れない。**
//
// ## 正直に書く限界(誇張しない)
//
// - **段階軸としてスロット側に実在するのは余白(`--space-1`〜`--space-6`)の1本だけである。**
//   他の6軸は単一スロット(または用途の違う2スロット)であり、そこに置いた「段」は
//   **表が決めた実値の組**であって、スロットの段階ではない。
// - **ADR-0047 限定3(部分更新の op が無い)により、余白だけ1段動かすときも25スロット
//   全部を書き直す。**「微調整」という語と、実際に流れる差分の量は食い違う。
// - **表が値を持つのは25スロットのうち13だけである**(配色9・書体1・寸法2 は持たない)。
//   残る12は `get_manifest` で読んだ今のテーマから写す。**テーマが未設定のアプリでは、
//   この表だけでは `set_theme` を組み立てられない。**
// - **本物の LLM を1度も呼んでいない。** 固定してあるのは**表の性質**だけである
//   (有限性 / スロット集合との双方向一致 / 実値がスキーマの pattern を通ること)。
// - **スロット名を書く場所がこれで4箇所目になる**(ADR-0046 限定1 は3箇所の完全一致を
//   機械検査で固定している)。**だから `vocabulary.test.ts` の一致検査は双方向である** ——
//   表が存在しないスロットを指していないことと、**26個目のスロットが増えた日に表が
//   取り残されないこと**(触る13 + 触らない12 = 25 の完全一致)を両方見る。

/** 統制語彙の軸ID。**軸1本 = スロットの組**(T00 の形2)。 */
export type DesignAxisId =
  | "space"
  | "font_size"
  | "line_height"
  | "border_width"
  | "corner_radius"
  | "shadow"
  | "focus_outline_width";

/** 軸の「段」。**持つのは行き先の実値**であって向きではない(T00 の形1)。 */
export type DesignAxisLevel = {
  readonly id: string;
  readonly label: string;
  /** スロット名 → そのまま `set_theme` に書ける実値。キー集合は軸の slots と一致する。 */
  readonly values: Readonly<Record<string, string>>;
};

export type DesignAxis = {
  readonly id: DesignAxisId;
  readonly label: string;
  readonly slots: readonly string[];
  /**
   * **スロット側に段階軸が実在するか。** `true` は余白だけである
   * (`$defs/theme` の description が自ら「余白の段階1 (最小)」と書いている)。
   * `false` の軸の「段」は**表が決めた実値の組**であって、スロットの段階ではない。
   */
  readonly slotStages: boolean;
  /** 値の小さいほうから大きいほうへ並べる(「1つ次の段」の意味をこの順序が決める)。 */
  readonly levels: readonly DesignAxisLevel[];
};

