/** 形容詞の行き先。**名指しの段**か、**段の並びで1つ隣**かの2種だけである。 */
export type DesignPhraseTarget =
  | { readonly kind: "level"; readonly level: string }
  | { readonly kind: "step"; readonly delta: 1 | -1 };

export type DesignPhrase = {
  readonly phrase: string;
  readonly axis: DesignAxisId;
  readonly target: DesignPhraseTarget;
};

/**
 * 統制語彙の全量(22通り)。**これが表そのものである。**
 *
 * **自然言語の全部を受けようとしていない**(審査記録 §4 S3-2 の不利な材料)——
 * 有限にすれば表に無い言い方は断られ、広げれば有限性が失われる。**ここでは有限を採り、
 * 断り方を `DESIGN_ADJECTIVE_TABLE` と `OUT_OF_SCOPE_BEHAVIOR` に書く**(憲法6)。
 */
