/**
 * **表が触らないと宣言したスロット(12)。**
 *
 * **これを持つことが「双方向」の後ろ半分である。** 触る13 とこの12 の和が
 * `$defs/theme` の25 と完全一致することを `vocabulary.test.ts` が固定しているので、
 * **26個目のスロットが増えた日、それを表に載せるか「載せない」と宣言するまで検査は赤いままになる。**
 * 片方向(表 → スロットの実在)だけだと、表は緑のまま静かに古くなる。
 */
export const DESIGN_ADJECTIVE_UNTOUCHED_SLOTS: readonly Readonly<{
  slot: string;
  reason: string;
}>[] = Object.freeze([
  Object.freeze({ slot: "--color-text", reason: "配色。形容詞から一意に決まらない" }),
  Object.freeze({ slot: "--color-text-secondary", reason: "配色。形容詞から一意に決まらない" }),
  Object.freeze({ slot: "--color-text-label", reason: "配色。形容詞から一意に決まらない" }),
  Object.freeze({ slot: "--color-text-placeholder", reason: "配色。形容詞から一意に決まらない" }),
  Object.freeze({ slot: "--color-danger", reason: "配色。形容詞から一意に決まらない" }),
  Object.freeze({ slot: "--color-page-background", reason: "配色。形容詞から一意に決まらない" }),
  Object.freeze({ slot: "--color-surface-highlight", reason: "配色。形容詞から一意に決まらない" }),
  Object.freeze({ slot: "--color-border", reason: "配色。形容詞から一意に決まらない" }),
  Object.freeze({ slot: "--focus-outline-color", reason: "配色。形容詞から一意に決まらない" }),
  Object.freeze({ slot: "--font-family-base", reason: "書体名は有限に列挙できない" }),
  Object.freeze({ slot: "--detail-label-width", reason: "個別の寸法。日常の形容詞に対応しない" }),
  Object.freeze({ slot: "--login-max-width", reason: "個別の寸法。日常の形容詞に対応しない" }),
] as const);

/**
 * 表を AI が読む散文へ組み立てる。
 *
 * **手書きの散文にしない。** 手で書くと、軸や段を足したときに文面だけが古いまま残る
 * (`VOCABULARY_SCOPE` を `DIFF_OPS` から組み立てているのと同じ理由)。
 */
function renderDesignAdjectiveTable(): string {
  const axisLines = DESIGN_ADJECTIVE_AXES.map((axis) => {
    const head =
      `・${axis.label}` +
      (axis.slotStages
        ? "(段階あり。スロット側が段階軸である)"
        : "(段階なし。表が決めた実値の組である)") +
      ` —— 対象スロット: ${axis.slots.join(" / ")}`;
    const levels = axis.levels
      .map((level) => {
        const values = axis.slots.map((slot) => `${slot}=${level.values[slot]}`).join(", ");
        return `    - ${level.label}: ${values}`;
      })
      .join("\n");
    return `${head}\n${levels}`;
  }).join("\n");

  const axisLabel = (id: DesignAxisId): string =>
    DESIGN_ADJECTIVE_AXES.find((axis) => axis.id === id)?.label ?? id;
  const levelLabel = (id: DesignAxisId, levelId: string): string =>
    DESIGN_ADJECTIVE_AXES.find((axis) => axis.id === id)?.levels.find(
      (level) => level.id === levelId,
    )?.label ?? levelId;

  const phraseLines = DESIGN_ADJECTIVE_PHRASES.map((entry) => {
    const destination =
      entry.target.kind === "level"
        ? `${axisLabel(entry.axis)}を「${levelLabel(entry.axis, entry.target.level)}」の段へ`
        : `${axisLabel(entry.axis)}を、段の並びで1つ${
            entry.target.delta === 1 ? "次の段(値が大きくなる向き)" : "前の段(値が小さくなる向き)"
          }へ`;
    return `    - 「${entry.phrase}」 → ${destination}`;
  }).join("\n");

  const untouchedLines = DESIGN_ADJECTIVE_UNTOUCHED_SLOTS.map(
    (entry) => `    - ${entry.slot}: ${entry.reason}`,
  ).join("\n");

  return (
    "\n【言葉と見た目の対応表】" +
    "「もっと余白を広く」のような日常の言葉での見た目の微調整は、" +
    `**あらかじめ決まった有限の表**でだけ受け付けます。表は${DESIGN_ADJECTIVE_AXES.length}軸・` +
    `${DESIGN_ADJECTIVE_PHRASES.length}通りの言い方だけで、AI がこの表を増やすことはできません。\n` +
    "**表の単位はスロット1個ではなく軸1本です** —— " +
    "例えば余白は6つのスロットで1軸なので、1つの言い方が6値を1組の別の6値へ差し替えます。\n" +
    "**表が持つのは「向き」ではなく行き先の実値です** —— " +
    "テーマの値には式・計算・参照を1つも書けないので、「1段上げる」という指定そのものが" +
    "マニフェストに書けません。表は段ごとの実値を持ち、AI がそれを選んで書きます。" +
    "**カーネルはこの表を1度も読みません**(「もっと」を解釈するのはこの説明文を読んでいるあなたで、" +
    "カーネルに届くのは展開された25スロットの実値だけです)。\n" +
    "**段階軸としてスロット側に実在するのは余白の1本だけです。** " +
    "他の軸は単一スロット(または用途の違う2スロット)で、そこに置いた「段」は表が決めた実値の組です —— " +
    "そうした軸で「もっと」を受け付けるときは、" +
    "**段階を1つ動かすのではなく、表が決めた別の実値へ差し替える**ことになります。\n" +
    `【軸と段 —— 行き先の実値】\n${axisLines}\n` +
    `【言い方の全量 —— ${DESIGN_ADJECTIVE_PHRASES.length}通り】\n${phraseLines}\n` +
    "【今の値がどの段とも一致しないとき】" +
    "`get_manifest` で読んだ今の値が表のどの段とも一致しないときは、" +
    "**勝手に近い段へ丸めない**でください。表の段を名指しで示し、どれにするかをユーザに選んでもらいます。\n" +
    "【表に無い言い方】" +
    "「かっこよく」「今風に」「かわいく」「明るい色に」「ボタンを目立たせて」のような言い方は" +
    "**この表にありません**。そのときは、まず**その言い方はこの表にありません**と正直に伝え、" +
    "**表にある言い方を示して選んでもらう**ようにしてください。" +
    "表に無い言い方を、似ているからという理由で表の段へ読み替えてはいけません。\n" +
    "【書くときの手順と、その代償】" +
    "**表が値を持つのは25スロットのうち13だけです。** " +
    "残る12スロット(配色9・書体1・寸法2)を表は1つも持ちません —— \n" +
    `${untouchedLines}\n` +
    "したがって `set_theme` を書くときは、" +
    "**`get_manifest` で今のテーマを読み、残る12スロットは写す**ことになります。" +
    "アプリにまだテーマが入っていない場合は、**この表だけでは set_theme を組み立てられません** —— " +
    "配色・書体・寸法をユーザと決める必要があります。" +
    "**部分更新の op はありません**ので、1つの軸だけを動かすときも" +
    "**25スロット全部を書き直す**ことになります" +
    "(「微調整」という言葉と、実際に流れる差分の量は食い違います。先に伝えてください)。\n" +
    "**この表はプロンプトであって強制力ではありません** —— " +
    "表の外の値を書いてもカーネルは拒みません(拒むのはスキーマの形とコントラスト比だけです)。" +
    "表どおりに動くことを保証する仕組みはありません。"
  );
}

