  // 差分を1つも禁じていない)。**効く / 効かないを混ぜないよう、両方を名指しで書く。**
  // **V4-M16-T10 / P-G28 + P-G22 / ADR-0090 限定10(Δ5)**: **10つ目(`emphasis`)が
  // 入ったので「9つだけ」は偽になった。** **`unit` と同じく `emphasis` は change_field で
