  // **発行できず**(発行は owner の UI のみ)、request_inbound_endpoint で**申請できるだけ**である。
  // V2-M5-T01(ADR-0041 限定1): 申請ツール(request_inbound_endpoint)を結線したので、代替案は
  // 「申請を出して owner の承認・発行を促す」まで具体化できる(送信 request_connection の対称)。
  "代替案の例: 外部からアプリへの取り込み経路(受信口)を AI が発行することはできない(発行は人間(owner)だけ)ので " +
  "(AI にできるのは request_inbound_endpoint で受信口を申請するところまでで、call_external は依然送信専用で応答取り込みは無い)、" +
  "受信が要るなら request_inbound_endpoint で申請を出して owner の承認・発行を促し、" +
  "当座のデータは insert_sample_data で人手で投入する案を出す" +
  "(AI 側で受信口を発行・有効化はできないので、「外部と自動で同期した」ことにはならない)。" +
  "グラフの代わりに、" +
  "list_view の columns と sort で見たい順に並べて見せる" +
  "(集計値そのものが要るなら、関数リソースの出力をテーブルに書いて見せる形は使えるが、描画はできない)。" +
  // **【`V8-M13-T04`。台帳 `Q-G30`】** **直前の1文の「描画はできない」は今日は不完全である**
  //   —— **集計表の中でだけ描ける。** **旧文を1バイトも消していない。**
  "(【2026-08-16 訂正】直前の「描画はできない」は集計表の外の話である —— " +
  "集計表(report_view)の report の chart には棒と折れ線の2種を書け、実際に描かれる。" +
  "代替案を出すのは、集計表の外にグラフを求められたときだけでよい)。" +
  // V3-M1-T06(ADR-0047 / Δ5): 旧例「見た目の変更の代わりに、ビューの columns と sort で…」は
  // **テーマ(set_theme)が入った時点で嘘になった** —— 配色・書体・余白は代替案ではなく本当に変えられる。
  // **代替案を出すべき対象はレイアウトと任意 CSS の側だけである**(そちらは今も語彙に無い)。
  "見た目のうち配色・書体・余白の段階などは**代替案ではなく本当に変えられる**ので、" +
  "代わりの案を出すのではなく set_theme で実際に変える" +
  "(ただし25スロット全部を書くことになる / 画面ごとには指定できない / 読めない配色は拒否される、" +
  "の3点は先に伝えること)。" +
  // V3-M4-T02(D-G8): 統制語彙の表が入った。**表があること自体を全ツールの説明文へ載せる** ——
  // 表の本体は apply_diff の説明文(`APPLY_DIFF_OP_EXAMPLES`)に載っているが、
  // **「表に無い言い方をどう断るか」は範囲外要求への振る舞いそのもの**なのでここに置く。
  // **逆向きの嘘に注意する**(審査記録 §4 S2)—— 表を足したあとに「表に無い言い方も何とかする」と
  // 振る舞えば、表の有限性を主張する文言のほうが嘘になる。だから断り方を明文で置く。
  "「もっと余白を広く」のような日常の言葉での微調整には、" +
  "apply_diff の説明文に**【言葉と見た目の対応表】**があり、受け付けられる言い方は有限である。" +
  "**表に無い言い方(「かっこよく」「今風に」など)は、似ているからという理由で表の段へ読み替えず、" +
  "その言い方はこの表にありませんと正直に伝えたうえで、表にある言い方を示して選んでもらうこと。**" +
  // V3-M2-T05(ADR-0050 / 0051 / Δ5): 旧例「レイアウト(段組・列幅・寄せ)と任意の CSS は
  // **語彙に無いので**…columns と sort を代わりに出す」は、**7軸が入った時点で嘘になった**
  // (段組・列幅・寄せは代替案ではなく本当に選べる)。**代替案が要るのは選択肢の外だけである。**
  // **V4-M16-T13(ADR-0093 限定1。Δ5)**: 7軸 → 8軸(8つ目 = 一覧の器の形)。
  // **V4-M19-T05(ADR-0118 限定1。Δ5)**: 8軸 → 9軸(9つ目 = 画面の詰まり具合)。
  "レイアウトのうち9軸(列の寄せ / 列の幅 / 件数表示とページャの位置 / 項目名と値の向き / " +
  "項目の段組数 / image の表示サイズ / long_text の切り詰め長 / 一覧の器の形 / 画面の詰まり具合)も**代替案ではなく本当に選べる**ので、" +
  "代わりの案を出すのではなく add_view / update_view の preset_ で始まるキーで実際に変える" +
  "(ただし選べるのは有限の選択肢だけ / 一度書いたキーは前進で外せない、の2点は先に伝えること)。" +
  "それに対し任意の CSS と、**選択肢の外**の見せ方(ピクセル座標・絶対配置・レスポンシブ・" +
  // **V4-M16-T11(ADR-0091 限定8。Δ5)**: 旧文は「入力フォームの見せ方・…」だった。
  // **入力フォームの見せ方のうち2軸は今日から本当に選べる**ので、**残る5軸**に狭めた。
  // **V4-M22-T07(ADR-0113 限定11。Δ5)**: 旧文は「…残る5軸・**1ページの件数**・罫線の…」
  // だった。**1ページの件数は今日から4つの段階値で選べる**ので、この列挙から外した。
  // **自由な数が書けないことは上の段落が述べている**(「語彙に無い」に丸めない)。
  "入力フォームの見せ方の残る5軸・罫線の見せ方など)は語彙に無いので、" +
  "ビューの columns と sort で表示する項目と並び順を変える案を代わりに出す。" +
  // V3-M5-T05(D-G5 / ADR-0055。Δ5): **逃げ道が入ったので「代替案しか出せない」は偽になった。**
  // **だが AI 自身が解決できるようになったのではない** —— 出せるのは「owner への申請」という
  // もう1つの出口であって、**申請しただけでは1ピクセルも変わらない。**
  "**あわせて逃げ道(任意 CSS)があることも伝える** —— " +
  "request_custom_css で owner に申請でき、owner が資産を発行すれば、その画面には実際に効く。" +
  "**ただし発行するのは人間であり、あなたは本文を1バイトも書けない。" +
  "申請しただけでは1ピクセルも変わらない。**" +
  "**代替案と申請のどちらを望むかは、勝手に決めずにユーザに選ばせること。**" +
  "**元に戻せる代替案があるなら、破壊的な操作より先にそれを示すこと** —— " +
  "例えば「感想メモを削除して」は remove_field で本当に消せますが、" +
  "update_view で一覧から外すだけなら入力済みの本文が残り、あとで戻せます。" +
  "両方を示して、どちらを望むかをユーザに選ばせてください。" +
  DESTRUCTIVE_SUBSTITUTE_CONSENT;

// ---------------------------------------------------------------------------
// V3-M5-T04: 逸脱の蓄積の検出と昇格の提案(`D-G10a`。ADR-0056 / 判定 = 将来送り・門外)
// ---------------------------------------------------------------------------
//
// **ここに置くもの**: 閾値のコード定数・数える対象の有限表・応答に逐語で載せる文言。
// **ここに置かないもの**: 集計そのもの(`src/mcp/tools/read.ts`)。
//
// **なぜ定数を `vocabulary.ts` に置くのか。** 歯止め1 の変更予定ファイルの宣言
// (`docs/plan/v3/records/v3-m5.md` §2 の T04 行)が「`src/mcp/vocabulary.ts`(閾値の
// コード定数と説明文)」と名指ししているためである。**マニフェスト(`schemas/`)に置けば Δ3、
// 予約名テーブル(`src/shared/system-tables.ts`)に置けば Δ2 が発火し、門外の根拠が消える。**
// **ユーザ決定 D-M4-4 が決めたのは値(3件)であって置き場ではない**(値と置き場を混ぜない)。

/**
 * 昇格を提案する閾値(件)。
 *
 * **値の出典はユーザ決定 D-M4-4(3件)であり、所見上の根拠は無い**(ADR-0056 §限界6 が
 * 自ら書いている)。**「件数を基準にすると基準そのものが検証不能になり、1本消して1本足すを
 * 素通りさせる」というこの製品が2度退けた形と同型である**(`v3-m4-gate-a-intake.md` §5 S3 の2番)。
 * **手当ては件数を単独で出さないことである** —— `report_drift` は群ごとに観測を全件列挙し、
 * **件数がその列挙から数え直せる**形でしか返さない(完了条件6)。
 */
export const DRIFT_PROMOTION_THRESHOLD = 3;

/**
 * 数える対象の集合(画面種別 → 数える `preset_*` キー)。
 *
 * **正は `schemas/manifest.schema.json` の `$defs/view` の `allOf` である。**
 * 7キーのうち **`list_view` では2キー・`detail_view` では3キーが `false` に落ちており、
 * `form` では7キーとも `false` である**(2026-07-27 実測)。**落ちている画面種別で数えると、
 * 「書けない」ことと「書かれていない」ことが同じ0として混ざる。**
 *
 * **【`V4-M16-T11` / `ADR-0091` 限定3 で偽になった】** 上の「`form` では7キーとも `false`」は
 * **2026-07-27 の実測としては正しいが、今日は成り立たない** —— **`ADR-0091` が
 * `preset_label_placement` と `preset_field_columns` の2つの `false` を form 分岐から外した。**
 * **旧文を1バイトも消していない。****したがって `form` の数える対象は 0 → 2 になった。**
 * **残る5キーは form でも今日どおり `false` であり、書かれていても数えない。**
 *
 * ここは正準スキーマの写しなので、`drift-report.test.ts` が `allOf` の分岐を実際に読んで
 * **両方向に**突き合わせる(8つ目のキーが生えたときも、分岐が変わったときも赤くなる)。
 *
 * **【`V4-M16-T13` / `ADR-0093` 限定1・限定2 で8つ目のキーが生えた】** 上の「7キーのうち」は
 * **2026-07-27 の実測としては正しいが、今日は成り立たない** —— **`preset_list_shape`
 * (一覧の器の形)が8つ目の `preset_` キーとして入り、`list_view` でだけ書ける。**
 * **旧文を1バイトも消していない。****したがって `list_view` の数える対象は 5 → 6 になり、
 * `form` と `detail_view` では今日も `false` である**(書かれていても数えない)。
 *
 * **【`V4-M19-T05` / `ADR-0118` 限定1 で9つ目のキーが生えた】** **`preset_density`
 * (画面の詰まり具合)は3種すべてに書ける** —— マニフェスト側の `allOf` のどの分岐でも
 * `false` にしていないためである。**旧文を1バイトも消していない。**
 * **したがって数える対象は `list_view` 6 → 7 / `form` 2 → 3 / `detail_view` 4 → 5 になった。**
 */
export const DRIFT_COUNTED_PRESET_KEYS: Readonly<Record<ViewType, readonly string[]>> =
  Object.freeze({
    list_view: Object.freeze([
      "preset_column_align",
      "preset_column_width",
      // **`V4-M19-T05` / `ADR-0118` 限定1**: 9つ目の `preset_` キー(画面の詰まり具合)。
      // **3種すべてに書けるので、3つの配列すべてに写す**(写さないと `drift-report.test.ts`
      // の突合が両方向で赤くなる)。
      "preset_density",
      "preset_image_size",
      // **`V4-M16-T13` / `ADR-0093` 限定2**: 8つ目の `preset_` キー(一覧の器の形)。
      // **正はスキーマの `allOf` である**ので、`list_view` でだけ書ける本キーをここにも写す
      // (写さないと `drift-report.test.ts` の突合が両方向で赤くなる)。
      "preset_list_shape",
      "preset_pager_position",
      "preset_text_preview",
    ]),
    // **`V4-M16-T11` / `ADR-0091` 限定3**: 着手前は `Object.freeze([])` だった。
    // **正はスキーマの `allOf` である**ので、form 分岐から外れた2キーをここにも写す
    // (写さないと `drift-report.test.ts` の突合が両方向で赤くなる)。
    // **`V4-M19-T05` / `ADR-0118` 限定1**: 9つ目のキーは form にも書ける(3種すべて)。
    form: Object.freeze(["preset_density", "preset_field_columns", "preset_label_placement"]),
    detail_view: Object.freeze([
      // **`V4-M19-T05` / `ADR-0118` 限定1**: 9つ目のキーは detail_view にも書ける。
      "preset_density",
      "preset_field_columns",
      "preset_image_size",
      "preset_label_placement",
      "preset_text_preview",
    ]),
    // **【`V8-M8` / 台帳 `Q-G1`。門A 本審査 = `V8-M7`】画面種別の4種目(集計表)。**
    // **数える対象は0本である** —— **`preset_` キーが1本も書けない**
    // (`schemas/manifest.schema.json` の `allOf` の `report_view` 分岐が9キーすべてを
    // `false` で閉じている)。**空配列は「まだ書いていない」ではなく「1本も書けない」である。**
    // **`drift-report.test.ts` が `allOf` の分岐を実際に読んで両方向に突き合わせるので、
    // いつか `report_view` に `preset_` キーが開いたらここが赤くなる。**
    report_view: Object.freeze([]),
  });

/** テーマの数える単位の名前(スロット名ではない。下の `DRIFT_THEME_COUNTING_RULE` を参照)。 */
export const DRIFT_THEME_UNIT = "app.theme";

/**
 * 「同趣旨」の判定規則(完了条件1)。**応答に逐語で載せる。**
 *
 * **判定が割れる形にしない**ことが完了条件そのものなので、規則は「同じキーに同じ値」だけに
 * 閉じてある。**ADR-0007 §1b が門の振り分けから追い出したのと同じ種類の判断
 * (似ているものをまとめる)を、機構の中心に置かない。**
 */
export const DRIFT_SAMENESS_RULE =
  "【同趣旨の判定規則】同趣旨とは「同じキーに同じ値が入っていること」だけを指します。" +
  "似ている値・意味が近い値は1件も同趣旨に数えません(段階値の隣どうしも別物として数えます)。" +
  "数える単位は(画面, キー, 値)の組です —— " +
  "1つの画面の同じキーに同じ値が何列ぶん書かれていても1件と数え(どの列に書かれていたかは fields に全件挙げます)、" +
  "1つの画面の同じキーに違う値が入っているときは値ごとに1件ずつ数えます。" +
  "したがって件数は「その(キー, 値)を書いている画面の数」に等しく、observations の画面IDから数え直せます。" +
  '値は文字列に正規化して比べます(項目の段組数の 1 / 2 は "1" / "2" として比べます)。';

/**
 * テーマの数え方(完了条件8)。**どちらを採ったかを応答に逐語で載せる。**
 *
 * **スロット単位で数えると「余白だけ1段」の調整1回が25件として立つ** —— `set_theme` は
 * 25スロット全部を書き直すからである(ADR-0047 限定3 / `$defs/theme` の `required` = 25)。
 * **値が1バイトも変わっていないスロットまで「調整した」と数えることになるので採らなかった。**
 */
export const DRIFT_THEME_COUNTING_RULE =
  "【テーマの数え方】テーマは app.theme を1つの数える単位とします(スロット単位では数えません)。" +
  "set_theme は25スロット全部を書き直すため(ADR-0047 限定3)、スロット単位で数えると" +
  "「余白だけ1段」の調整1回が25件として立ち、値が1バイトも変わっていないスロットまで" +
  "「調整した」と数えることになるからです。" +
  "数えた根拠として、25スロットの値そのものを slots に全件添えます。";

/**
 * テーマ側の限界(完了条件8 の「帰結」)。**応答の limitations に必ず載せる。**
 *
 * **黙って効かないのは憲法6 違反である** —— テーマ側は数えているのに閾値に達し得ない、
 * という事実を隠さない。
 */
export const DRIFT_THEME_LIMITATION =
  "テーマは1アプリに高々1つしか存在しないため、テーマ側の件数は常に0件か1件であり、閾値に達することはありません" +
  " —— つまりこの機能はテーマの蓄積を検出できません。" +
  "スロット単位で数えても各スロットが1件ずつ立つだけで、やはり閾値には達しません。" +
  "数え方の選択が変えるのは列挙の行数(25行か1行か)だけです。" +
  "実際に検出できるのは、画面ごとのプリセット(preset_ で始まるキー)の蓄積だけです。";

